const incoming = $json.body;

// Debug logging - remove after testing
console.log('Incoming data structure:', JSON.stringify(incoming, null, 2));

// Validate nested input structure
if (!incoming.context?.org_id) {
  throw new Error('MISSING_REQUIRED_FIELD:org_id');
}
if (!incoming.context?.expense_record_id) {
  throw new Error('MISSING_REQUIRED_FIELD:expense_record_id');
}
if (!incoming.decision?.action) {
  throw new Error('MISSING_REQUIRED_FIELD:decision');
}

const allowed = ['APPROVED', 'REJECTED', 'approved', 'rejected', 'approve', 'reject'];
const decision = incoming.decision.action.toUpperCase();

if (!allowed.map(d => d.toUpperCase()).includes(decision)) {
  throw new Error(`INVALID_DECISION:${incoming.decision.action}`);
}

// Normalize to canonical nested contract
const payload = {
  context: {
    org_id: incoming.context.org_id,
    expense_record_id: incoming.context.expense_record_id
  },
  decision: {
    action: decision === 'REJECT' ? 'REJECTED' : 'APPROVED', // Normalize action
    actor: 'system',
    notes: null
  }
};

return [{ json: payload }];
